  br i1 %cond, label %if, label %end

if:
  %shuf_y = shufflevector <4 x i32> %y, <4 x i32> { 10, 20, 30, 40 }, 0, 5, 0, 5
  br label %end

end:
  %phi = phi <4 x i32> [ %shuf_x, %entry ], [ %shuf_y, %if ]
  ret <4 x i32> %phi
}
